(int16 wordPos, uint8 bitPos) = TickLib.position(startTick.compress(self.tickSpacing));
self.currentWord = self.manager.getPoolBitmapInfo(self.poolId, wordPos);

bool initialized;
(initialized, bitPos) = self.currentWord.nextBitPosLte(bitPos);
self.currentTick = TickLib.toTick(wordPos, bitPos, self.tickSpacing);

if (!initialized) {
    while (self.currentTick > self.endTick) {
        (wordPos, bitPos) = TickLib.position(TickLib.compress(self.currentTick - 1, self.tickSpacing));
        self.currentWord = self.manager.getPoolBitmapInfo(self.poolId, wordPos);
        (initialized, bitPos) = self.currentWord.nextBitPosLte(bitPos);
        self.currentTick = TickLib.toTick(wordPos, bitPos, self.tickSpacing);
        if (initialized) break;
    }

    if (!initialized && self.currentTick <= self.endTick) {
        self.currentTick = self.endTick;
    }
}

